// Folder names must not contain characters Drive/other tools choke on.
function sanitize(name) {
  return String(name || 'Unknown')
    .replace(/[\\/:*?"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 100) || 'Unknown';
}
const j = $json;
return [{
  json: {
    ...j,
    labelFolderName: sanitize(j.label),
    dateFolderName: sanitize(j.receivedDateFolder),
    senderFolderName: sanitize(j.senderName),
  }
}];

// Find-or-create the 'Label' folder. Reuses it if present so we
// never create duplicate folders across runs.
const j = $json;
const parentId = j.driveRootFolderId;
const folderName = j.labelFolderName;

const searchQuery = `name='${folderName.replace(/'/g, "\\'")}' and '${parentId}' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false`;

const found = await this.helpers.httpRequestWithAuthentication.call(
  this,
  'googleDriveOAuth2Api',
  {
    method: 'GET',
    url: 'https://www.googleapis.com/drive/v3/files',
    qs: { q: searchQuery, fields: 'files(id,name)', spaces: 'drive' },
    json: true,
  }
);

let folderId;
if (found.files && found.files.length > 0) {
  folderId = found.files[0].id;
} else {
  const created = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleDriveOAuth2Api',
    {
      method: 'POST',
      url: 'https://www.googleapis.com/drive/v3/files',
      body: { name: folderName, mimeType: 'application/vnd.google-apps.folder', parents: [parentId] },
      json: true,
    }
  );
  folderId = created.id;
}

return [{ json: { ...j, labelFolderId: folderId } }];

