// Collect every upload result, then carry the original email data
// back to the parent workflow so it can be logged in Sheets.
// The Split node preserves all parent fields on each split item, so each
// upload item still has messageId, senderName, label, etc.
const input = $input.first().json;
const uploads = input.uploads || [];
const driveFileIds = uploads.map(u => u.json && u.json.id).filter(Boolean);
const driveFileLinks = uploads.map(u => u.json && u.json.webViewLink).filter(Boolean);
const anyFailed = uploads.some(u => u.json && u.json.error);

// Recover the original email metadata from the first upload item
// (it carries the full parent payload through the Split → Download → Upload chain)
const emailMeta = (uploads[0] && uploads[0].json) || input;

return [{
  json: {
    ...emailMeta,
    driveFileIds,
    driveFileLinks,
    uploadedCount: driveFileIds.length,
    uploadStatus: anyFailed ? 'error' : 'ok',
  }
}];
